import React, { useState } from 'react';
import { KeyIcon, CheckIcon, XCircleIcon, CogIcon } from './icons';

interface SettingsModalProps {
    isOpen: boolean;
    onClose: () => void;
    onSelectKey: () => Promise<void>;
    hasAiStudio: boolean;
    hasActiveKey: boolean;
    customApiKey: string;
    onSaveCustomKey: (key: string) => void;
}

const SettingsModal: React.FC<SettingsModalProps> = ({ 
    isOpen, 
    onClose, 
    onSelectKey, 
    hasAiStudio, 
    hasActiveKey,
    customApiKey,
    onSaveCustomKey
}) => {
    const [tempKey, setTempKey] = useState(customApiKey);
    const [isSelecting, setIsSelecting] = useState(false);

    if (!isOpen) return null;

    const handleSave = () => {
        onSaveCustomKey(tempKey);
        onClose();
    };

    const handleGoogleSelect = async () => {
        setIsSelecting(true);
        try {
            await onSelectKey();
        } finally {
            setIsSelecting(false);
        }
    };

    return (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-slate-900/50 backdrop-blur-sm p-4 animate-fade-in">
            <div className="bg-white dark:bg-slate-800 rounded-2xl shadow-2xl w-full max-w-md overflow-hidden border border-slate-200 dark:border-slate-700">
                <div className="p-6">
                    <div className="flex justify-between items-center mb-6">
                        <h2 className="text-xl font-bold text-slate-800 dark:text-white flex items-center gap-2">
                            <CogIcon className="w-6 h-6 text-slate-500" />
                            Connection Settings
                        </h2>
                        <button onClick={onClose} className="text-slate-400 hover:text-slate-600 dark:hover:text-slate-300">
                            <XCircleIcon className="w-6 h-6" />
                        </button>
                    </div>

                    <div className="space-y-6">
                        {/* Option 1: Google Subscription */}
                        {hasAiStudio && (
                            <div className="bg-blue-50 dark:bg-blue-900/10 p-4 rounded-xl border border-blue-100 dark:border-blue-900/30">
                                <h3 className="text-sm font-semibold text-blue-900 dark:text-blue-100 mb-2">Option A: Google Cloud Subscription</h3>
                                <p className="text-xs text-blue-700 dark:text-blue-300 mb-4">
                                    Use your existing Google Cloud project or AI Studio subscription. Recommended for ease of use.
                                </p>
                                <button
                                    onClick={handleGoogleSelect}
                                    disabled={isSelecting}
                                    className="w-full flex items-center justify-center gap-2 px-4 py-2.5 bg-blue-600 hover:bg-blue-700 text-white rounded-lg font-medium transition-colors shadow-sm disabled:opacity-50"
                                >
                                    {isSelecting ? (
                                        <div className="w-4 h-4 border-2 border-white/50 border-t-white rounded-full animate-spin" />
                                    ) : (
                                        <KeyIcon className="w-4 h-4" />
                                    )}
                                    {hasActiveKey ? 'Connected via Google' : 'Connect Google Account'}
                                </button>
                                {hasActiveKey && !tempKey && (
                                    <div className="mt-2 flex items-center justify-center gap-1 text-xs text-green-600 dark:text-green-400 font-medium">
                                        <CheckIcon className="w-3.5 h-3.5" />
                                        Active Connection
                                    </div>
                                )}
                            </div>
                        )}

                        {/* Option 2: Custom API Key */}
                        <div className="bg-slate-50 dark:bg-slate-700/30 p-4 rounded-xl border border-slate-200 dark:border-slate-700">
                            <h3 className="text-sm font-semibold text-slate-800 dark:text-slate-200 mb-2">
                                {hasAiStudio ? 'Option B: ' : ''}Manual API Key
                            </h3>
                            <p className="text-xs text-slate-500 dark:text-slate-400 mb-3">
                                Enter a specific Gemini API key. This overrides the Google Subscription if set.
                            </p>
                            <input
                                type="password"
                                value={tempKey}
                                onChange={(e) => setTempKey(e.target.value)}
                                placeholder="AIzaSy..."
                                className="w-full px-3 py-2 bg-white dark:bg-slate-800 border border-slate-300 dark:border-slate-600 rounded-lg text-sm focus:ring-2 focus:ring-blue-500 focus:border-transparent outline-none transition-all mb-3"
                            />
                            <div className="text-[10px] text-slate-400 dark:text-slate-500 mb-3">
                                * Key is stored in your browser's session memory only.
                            </div>
                            <button
                                onClick={handleSave}
                                className="w-full py-2 bg-slate-800 dark:bg-slate-600 hover:bg-slate-900 dark:hover:bg-slate-500 text-white rounded-lg text-sm font-medium transition-colors"
                            >
                                {tempKey ? 'Use This Key' : 'Clear Key'}
                            </button>
                        </div>
                    </div>
                </div>
            </div>
        </div>
    );
};

export default SettingsModal;

import { GoogleGenAI, GenerateContentResponse, Content, Part, GenerateContentParameters } from "@google/genai";
import type { ChatMessage, ChatMode, UploadedFile } from '../types';
import { MODEL_CONFIGS, SYSTEM_INSTRUCTION } from '../constants';

// Helper to convert our app's message format to Gemini's format.
const messageToContent = (message: ChatMessage, isHistory: boolean = false): Content => {
    const parts: Part[] = [];

    // If the message has a persistent file attached
    if (message.filePreview) {
        // COST OPTIMIZATION:
        // We strictly control when to send base64 image data.
        // Sending high-res images in the chat history (every turn) is extremely expensive and redundant
        // because the model (Assistant) has already processed and described the image in the previous turn.
        // We only send the binary data if it's the CURRENT payload, not history.

        const hasData = message.filePreview.base64 && message.filePreview.type;
        const shouldSendImage = !isHistory && hasData;

        if (shouldSendImage) {
            parts.push({
                inlineData: {
                    mimeType: message.filePreview.type,
                    data: message.filePreview.base64!,
                }
            });
        } else {
            // "Zombie" / Context Preservation Logic:
            // If data is missing (reload) OR if we intentionally stripped it (history optimization),
            // we inject a System Note. This prevents the model from hallucinating that it "can't see" anything,
            // by explicitly telling it to rely on memory/previous analysis.

            const isImage = message.filePreview.type.startsWith('image/');

            // We only inject a text placeholder if this was an image.
            // Text files are already embedded in `message.content` by App.tsx logic, so they don't need this.
            if (isImage) {
                 parts.push({ 
                    text: `[System Note: The user attached an image named "${message.filePreview.name}" in a previous turn. To conserve tokens, the image data is not re-sent. Please rely on your previous analysis of this image.]` 
                });
            } 
        }
    }

    if (message.content) {
        let textToSend = message.content;
        parts.push({ text: textToSend });
    }

    return { role: message.role, parts };
};

const consolidateContents = (contents: Content[]): Content[] => {
    if (contents.length === 0) return [];

    const consolidated: Content[] = [];
    let currentRole = contents[0].role;
    let currentParts: Part[] = [...contents[0].parts];

    for (let i = 1; i < contents.length; i++) {
        const msg = contents[i];
        if (msg.role === currentRole) {
            currentParts = [...currentParts, ...msg.parts];
        } else {
            consolidated.push({ role: currentRole, parts: currentParts });
            currentRole = msg.role;
            currentParts = [...msg.parts];
        }
    }
    consolidated.push({ role: currentRole, parts: currentParts });

    return consolidated;
};

interface GenerateResponseOptions {
  file?: UploadedFile;
  responseType?: 'json' | 'text';
  location?: { latitude: number; longitude: number };
  apiKey?: string;
}

export const generateResponseStream = async function* (
  prompt: string,
  history: ChatMessage[],
  mode: ChatMode,
  options?: GenerateResponseOptions
): AsyncGenerator<GenerateContentResponse> {
  const finalApiKey = options?.apiKey || process.env.API_KEY;
  if (!finalApiKey) throw new Error("API Key missing. Please set it in Settings.");

  const ai = new GoogleGenAI({ apiKey: finalApiKey });

  const modelConfig = MODEL_CONFIGS[mode];
  const file = options?.file;

  // 1. Filter out completely empty messages (safety check)
  const rawHistory = history.filter(msg => {
     return (msg.content && msg.content.trim() !== '') || (msg.filePreview !== undefined);
  });

  // 2. INTELLIGENT CONTEXT PRUNING ("Sticky Files")
  // In a medical context, files (X-Rays, PDFs) are the source of truth.
  // We MUST preserve them, even if the conversation gets long.
  // A simple `slice(-15)` would delete the Patient Chart if the doctor asks 16 questions.

  const MAX_TEXT_TURNS = 15; // Keep last 15 exchanges of text

  // Identify "Medical Records" (Messages with file attachments)
  const medicalRecords = rawHistory.filter(msg => msg.filePreview !== undefined);

  // Identify "Conversation" (Text-only messages)
  const conversation = rawHistory.filter(msg => msg.filePreview === undefined);

  // Prune only the conversation, keep ALL medical records
  const recentConversation = conversation.slice(-MAX_TEXT_TURNS);

  // Re-assemble and sort by original order to maintain logical flow
  const historyToProcess = [...medicalRecords, ...recentConversation].sort((a, b) => {
      return rawHistory.indexOf(a) - rawHistory.indexOf(b);
  });

  // Map history to API Content objects.
  // Pass 'true' to isHistory to strip expensive image binaries, but KEEP text.
  let contents: Content[] = historyToProcess.map(msg => messageToContent(msg, true));
  contents = consolidateContents(contents);

  const currentMessageParts: Part[] = [];

  if (file) {
    currentMessageParts.push({
      inlineData: {
        mimeType: file.type,
        data: file.base64,
      },
    });
  }

  currentMessageParts.push({ text: prompt });

  contents.push({ role: 'user', parts: currentMessageParts });

  const responseStream = await ai.models.generateContentStream({
    model: modelConfig.model,
    contents: contents,
    config: {
      systemInstruction: SYSTEM_INSTRUCTION,
      ...modelConfig.config,
      ...(options?.responseType === 'json' ? { responseMimeType: 'application/json' } : {}),
      // GROUNDING: If options provide location, inject it into toolConfig
      ...(options?.location ? {
         toolConfig: {
             retrievalConfig: {
                 latLng: {
                     latitude: options.location.latitude,
                     longitude: options.location.longitude
                 }
             }
         } as any
      } : {})
    },
  });

  for await (const chunk of responseStream) {
    yield chunk;
  }
};

import { useState, useRef, useCallback, useEffect } from 'react';
import { GoogleGenAI, LiveServerMessage, Modality, Blob } from "@google/genai";
import { MODEL_CONFIGS, SYSTEM_INSTRUCTION } from '../constants';
import { ChatMode, ChatMessage } from '../types';

declare global {
  interface Window {
    webkitAudioContext: typeof AudioContext;
  }
}

const encode = (bytes: Uint8Array) => {
  let binary = '';
  const len = bytes.byteLength;
  for (let i = 0; i < len; i++) {
    binary += String.fromCharCode(bytes[i]);
  }
  return btoa(binary);
}

const decode = (base64: string) => {
  const binaryString = atob(base64);
  const len = binaryString.length;
  const bytes = new Uint8Array(len);
  for (let i = 0; i < len; i++) {
    bytes[i] = binaryString.charCodeAt(i);
  }
  return bytes;
}

async function decodeAudioData(
  data: Uint8Array,
  ctx: AudioContext,
  sampleRate: number,
  numChannels: number,
): Promise<AudioBuffer> {
  const dataInt16 = new Int16Array(data.buffer);
  const frameCount = dataInt16.length / numChannels;
  const buffer = ctx.createBuffer(numChannels, frameCount, sampleRate);

  for (let channel = 0; channel < numChannels; channel++) {
    const channelData = buffer.getChannelData(channel);
    for (let i = 0; i < frameCount; i++) {
      channelData[i] = dataInt16[i * numChannels + channel] / 32768.0;
    }
  }
  return buffer;
}

const createBlob = (data: Float32Array): Blob => {
  const l = data.length;
  const int16 = new Int16Array(l);
  for (let i = 0; i < l; i++) {
    const clamped = Math.max(-1, Math.min(1, data[i]));
    int16[i] = clamped < 0 ? clamped * 0x8000 : clamped * 0x7FFF;
  }
  return {
    data: encode(new Uint8Array(int16.buffer)),
    mimeType: 'audio/pcm;rate=16000',
  };
}

type LiveSession = Awaited<ReturnType<InstanceType<typeof GoogleGenAI>['live']['connect']>>;

export interface UseLiveSessionReturn {
    isLive: boolean;
    transcript: { userInput: string; modelOutput: string };
    startSession: (history?: ChatMessage[], apiKey?: string) => Promise<void>;
    stopSession: () => Promise<void>;
    error: string | null;
}

export const useLiveSession = (onTurnComplete?: (userInput: string, modelOutput: string) => void): UseLiveSessionReturn => {
    const [isLive, setIsLive] = useState(false);
    const [transcript, setTranscript] = useState({ userInput: '', modelOutput: '' });
    const [error, setError] = useState<string | null>(null);

    const accumulatedTranscriptRef = useRef({ userInput: '', modelOutput: '' });
    const liveSessionRef = useRef<LiveSession | null>(null);
    const inputAudioContextRef = useRef<AudioContext | null>(null);
    const outputAudioContextRef = useRef<AudioContext | null>(null);
    const audioSourcesRef = useRef<Set<AudioBufferSourceNode>>(new Set());
    const nextStartTimeRef = useRef<number>(0);
    const scriptProcessorRef = useRef<ScriptProcessorNode | null>(null);
    const mediaStreamSourceRef = useRef<MediaStreamAudioSourceNode | null>(null);
    const isStoppingRef = useRef(false);

    const stopSession = useCallback(async () => {
        if (isStoppingRef.current) return;
        isStoppingRef.current = true;

        try {
            // 1. Close the session socket first
            if (liveSessionRef.current) {
                liveSessionRef.current.close();
                liveSessionRef.current = null;
            }

            // 2. Disconnect audio nodes
            scriptProcessorRef.current?.disconnect();
            mediaStreamSourceRef.current?.disconnect();
            scriptProcessorRef.current = null;
            mediaStreamSourceRef.current = null;

            // 3. Stop all playing audio
            audioSourcesRef.current.forEach(source => {
                try { source.stop(); } catch(e) {}
            });
            audioSourcesRef.current.clear();

            // 4. Suspend AudioContexts cleanly
            if (inputAudioContextRef.current && inputAudioContextRef.current.state === 'running') {
                try { await inputAudioContextRef.current.suspend(); } catch(e) { console.warn("Input suspend failed", e); }
            }
            if (outputAudioContextRef.current && outputAudioContextRef.current.state === 'running') {
                try { await outputAudioContextRef.current.suspend(); } catch(e) { console.warn("Output suspend failed", e); }
            }

            nextStartTimeRef.current = 0;

            // 5. Finalize transcript
            if ((accumulatedTranscriptRef.current.userInput || accumulatedTranscriptRef.current.modelOutput) && onTurnComplete) {
                onTurnComplete(accumulatedTranscriptRef.current.userInput, accumulatedTranscriptRef.current.modelOutput);
            }

            accumulatedTranscriptRef.current = { userInput: '', modelOutput: '' };
            setTranscript({ userInput: '', modelOutput: '' });

        } catch (e) {
            console.error("Error during session stop:", e);
        } finally {
            setIsLive(false);
            isStoppingRef.current = false;
        }
    }, [onTurnComplete]);

    const startSession = useCallback(async (history: ChatMessage[] = [], apiKey?: string) => {
        if (isLive || isStoppingRef.current) return;

        setError(null);
        accumulatedTranscriptRef.current = { userInput: '', modelOutput: '' };

        const finalKey = apiKey || process.env.API_KEY;
        if (!finalKey) {
            setError("API Key missing. Check settings.");
            return;
        }

        try {
            // SAFETY CHECK: Check if mediaDevices API exists (it doesn't on insecure HTTP)
            if (!navigator.mediaDevices || !navigator.mediaDevices.getUserMedia) {
                throw new Error("Media API not available. Secure context (HTTPS) required.");
            }

            // 1. Initialize Audio Contexts (Singleton Pattern)
            if (!inputAudioContextRef.current || inputAudioContextRef.current.state === 'closed') {
                inputAudioContextRef.current = new (window.AudioContext || window.webkitAudioContext)({ sampleRate: 16000 });
            }
            if (!outputAudioContextRef.current || outputAudioContextRef.current.state === 'closed') {
                outputAudioContextRef.current = new (window.AudioContext || window.webkitAudioContext)({ sampleRate: 24000 });
            }

            // Resume if suspended
            if (inputAudioContextRef.current.state === 'suspended') await inputAudioContextRef.current.resume();
            if (outputAudioContextRef.current.state === 'suspended') await outputAudioContextRef.current.resume();

            // 2. Get User Media (Critical Failure Point for No Mic)
            let stream: MediaStream;
            try {
                stream = await navigator.mediaDevices.getUserMedia({ 
                    audio: {
                        echoCancellation: true,
                        noiseSuppression: true,
                        autoGainControl: true,
                    } 
                });
            } catch (mediaError: any) {
                // Handle specific hardware errors here
                if (mediaError.name === 'NotFoundError' || mediaError.name === 'DevicesNotFoundError') {
                    throw new Error("No microphone found on this device.");
                }
                if (mediaError.name === 'NotAllowedError' || mediaError.name === 'PermissionDeniedError') {
                    throw new Error("Microphone permission denied by user.");
                }
                throw mediaError; // Rethrow other errors to be caught by outer catch
            }

            setIsLive(true);

            const ai = new GoogleGenAI({ apiKey: finalKey });

            // 3. Build Context String
            let contextString = "";
            if (history.length > 0) {
                const recentHistory = history.slice(-6).filter(m => m.content).map(m => {
                    const content = m.content.length > 200 ? m.content.substring(0, 200) + "..." : m.content;
                    return `${m.role.toUpperCase()}: ${content}`;
                }).join("\n");
                contextString = `\n\n[CONTEXT: ${recentHistory}]`;
            }

            // 4. Connect to Live API
            const sessionPromise = ai.live.connect({
                model: MODEL_CONFIGS[ChatMode.Live].model,
                config: {
                    ...MODEL_CONFIGS[ChatMode.Live].config,
                    systemInstruction: SYSTEM_INSTRUCTION + contextString
                },
                callbacks: {
                    onopen: async () => {
                        if (!inputAudioContextRef.current) return;
                        // Setup Input Stream
                        mediaStreamSourceRef.current = inputAudioContextRef.current.createMediaStreamSource(stream);
                        scriptProcessorRef.current = inputAudioContextRef.current.createScriptProcessor(4096, 1, 1);

                        scriptProcessorRef.current.onaudioprocess = (audioProcessingEvent) => {
                            if (!inputAudioContextRef.current || inputAudioContextRef.current.state !== 'running') return;
                            const inputData = audioProcessingEvent.inputBuffer.getChannelData(0);
                            const pcmBlob = createBlob(inputData);
                            sessionPromise.then((session) => {
                                session.sendRealtimeInput({ media: pcmBlob });
                            });
                        };
                        mediaStreamSourceRef.current.connect(scriptProcessorRef.current);
                        scriptProcessorRef.current.connect(inputAudioContextRef.current.destination);
                    },
                    onmessage: async (message: LiveServerMessage) => {
                        if (message.serverContent?.inputTranscription) {
                            accumulatedTranscriptRef.current.userInput += message.serverContent.inputTranscription.text;
                            setTranscript(prev => ({ ...prev, userInput: accumulatedTranscriptRef.current.userInput }));
                        }
                        if (message.serverContent?.outputTranscription) {
                            accumulatedTranscriptRef.current.modelOutput += message.serverContent.outputTranscription.text;
                            setTranscript(prev => ({ ...prev, modelOutput: accumulatedTranscriptRef.current.modelOutput }));
                        }

                        if (message.toolCall) {
                             for (const fc of message.toolCall.functionCalls) {
                                const result = { result: "Success" };
                                sessionPromise.then((session) => {
                                    if (liveSessionRef.current) {
                                        session.sendToolResponse({
                                            functionResponses: [{ id: fc.id, name: fc.name, response: result }]
                                        });
                                    }
                                });
                            }
                        }

                        const audioData = message.serverContent?.modelTurn?.parts?.[0]?.inlineData?.data;
                        if (audioData && outputAudioContextRef.current) {
                            const outCtx = outputAudioContextRef.current;
                            if (outCtx.state === 'suspended') await outCtx.resume();

                            nextStartTimeRef.current = Math.max(nextStartTimeRef.current, outCtx.currentTime);
                            const audioBuffer = await decodeAudioData(decode(audioData), outCtx, 24000, 1);

                            const source = outCtx.createBufferSource();
                            source.buffer = audioBuffer;
                            source.connect(outCtx.destination);
                            source.addEventListener('ended', () => { audioSourcesRef.current.delete(source); });
                            source.start(nextStartTimeRef.current);
                            nextStartTimeRef.current += audioBuffer.duration;
                            audioSourcesRef.current.add(source);
                        }

                         if (message.serverContent?.interrupted) {
                            audioSourcesRef.current.forEach(source => { try { source.stop(); } catch (e) {} });
                            audioSourcesRef.current.clear();
                            nextStartTimeRef.current = 0;
                        }

                        if (message.serverContent?.turnComplete) {
                             if (onTurnComplete) {
                                onTurnComplete(accumulatedTranscriptRef.current.userInput, accumulatedTranscriptRef.current.modelOutput);
                            }
                            accumulatedTranscriptRef.current = { userInput: '', modelOutput: '' };
                            setTranscript({ userInput: '', modelOutput: '' });
                        }
                    },
                    onerror: (e: ErrorEvent) => {
                        console.error('Live session error:', e);
                        stopSession();
                    },
                    onclose: () => { stopSession(); },
                },
            });

            const session = await sessionPromise;
            if (isStoppingRef.current) {
                session.close();
                return;
            }
            liveSessionRef.current = session;

        } catch (e: any) {
            console.error("Live start failed", e);
            stopSession();

            let errMsg = "Microphone or connection failed.";
            const msg = e.message || e.toString();

            // Map error to friendly message
            if (msg.includes('No microphone found')) {
                errMsg = "No microphone detected. Please connect a microphone.";
            } else if (msg.includes('permission denied')) {
                errMsg = "Microphone access denied. Please allow permissions.";
            } else if (msg.includes('Media API not available')) {
                errMsg = "Voice is not supported in this browser context (HTTPS required).";
            } else {
                errMsg = "Live connection failed: " + msg;
            }

            setError(errMsg);
        }
    }, [isLive, stopSession, onTurnComplete]);

    useEffect(() => {
        return () => { if (isLive) stopSession(); };
    }, [stopSession]);

    return { isLive, transcript, startSession, stopSession, error };
};

