                                </div>
                                {hasActiveKey && !tempKey && (
                                    <div className="mt-3 pt-3 border-t border-blue-200 dark:border-blue-800/50 flex items-center justify-center gap-1.5 text-xs text-green-600 dark:text-green-400 font-bold">
